origin.script:
'use strict';
const audio = engine.registerAudioBuffers(engine.AUDIO_RESOLUTION_64);
const bars = [];
export function init(value) {
    // the left channel's 64 bands at the top, the right channel's at the bottom, growing up from a line
    for (const [row, base] of [[0, 600], [1, 100]]) {
        for (let i = 0; i < 64; i++) {
            bars.push(thisScene.createLayer({image: 'models/util/solidlayer.json', name: 'bar ' + row + ' ' + i,
                origin: new Vec3(60 + i * 28, base, 0), size: new Vec2(20, 2),
                color: row === 0 ? new Vec3(1, 0.6, 0.2) : new Vec3(0.2, 0.7, 1)}));
        }
    }
    return value;
}
export function update(value) {
    for (let i = 0; i < 64; i++) {
        for (const [row, values] of [[0, audio.left], [1, audio.right]]) {
            const bar = bars[row * 64 + i];
            const height = Math.max(2, values[i] * 400);
            bar.scale = new Vec3(1, height / 2, 1);
            bar.origin = new Vec3(bar.origin.x, (row === 0 ? 600 : 100) + height / 2, 0);
        }
    }
    return value;
}

scriptframe.script:
'use strict';

export function update(value) {
	return Math.floor(engine.runtime * 30 + 0.5);
}

press.script:
'use strict';

let last = 0;
let wasDown = false;

export function update(value) {
	try {
		const down = !!input.cursorLeftDown;
		if (down && !wasDown) last = Math.min(Math.floor(engine.runtime * 30 + 0.5) + 1, 4094);
		wasDown = down;
		return last;
	} catch (e) {
		return 4095;
	}
}

date_day.script:
'use strict';

export function update(value) {
	return Math.floor(Date.now() / 86400000) - 18262;
}

date_centis.script:
'use strict';

export function update(value) {
	return Math.floor((Date.now() % 86400000) / 10);
}

timezone.script:
'use strict';

export function update(value) {
	return new Date().getTimezoneOffset() + 1024;
}

camerax.script:
'use strict';

function quantise(value, offset, scale, bits) {
	const most = Math.pow(2, bits) - 1;
	return Math.min(Math.max(Math.floor((value + offset) * scale + 0.5), 0), most);
}

export function update(value) {
	try {
		return quantise(thisScene.getCameraTransforms().eye.x, 32768, 256, 24);
	} catch (e) {
		return 16777215;
	}
}

